from typing import List

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

# Enzyme table: name -> recognition site (cut is at the start of the site,
# e.g. EcoRI G^AATTC cuts immediately before AATTC).
ENZYMES = {
    "EcoRI": "GAATTC",
    "BamHI": "GGATCC",
    "HindIII": "AAGCTT",
}


class DigestRequest(BaseModel):
    seq: str
    enzymes: List[str]
    circular: bool = False


app = FastAPI(title="digest service")


def _validate(seq: str, enzymes: List[str]) -> None:
    if not seq:
        raise HTTPException(status_code=422, detail="sequence must be non-empty")
    bad = sorted({c for c in seq.upper() if c not in "ACGT"})
    if bad:
        raise HTTPException(
            status_code=422,
            detail="sequence contains non-ACGT characters: " + ", ".join(bad),
        )
    unknown = [e for e in enzymes if e not in ENZYMES]
    if unknown:
        raise HTTPException(
            status_code=422,
            detail="unknown enzyme(s): " + ", ".join(unknown),
        )


def _cuts(seq: str, sites: List[str], circular: bool) -> List[int]:
    """Return sorted cut positions (bases counted from the 5' end)."""
    n = len(seq)
    cuts = set()
    for site in sites:
        m = len(site)
        text = seq + seq[: m - 1] if circular else seq
        for i in range(len(text) - m + 1):
            if text[i : i + m] == site:
                cuts.add((i + 1) % n if circular else i + 1)
    return sorted(cuts)


def _fragments(n: int, cuts: List[int], circular: bool) -> List[int]:
    if not cuts:
        return [n]
    if circular:
        points = [0] + cuts
        return [b - a for a, b in zip(points, points[1:] + [points[0] + n])]
    points = [0] + cuts + [n]
    return [b - a for a, b in zip(points, points[1:])]


@app.post("/digest")
def digest(req: DigestRequest):
    _validate(req.seq, req.enzymes)
    seq = req.seq.upper()
    sites = [ENZYMES[e] for e in req.enzymes]
    cuts = _cuts(seq, sites, req.circular)
    return {
        "seq": seq,
        "enzymes": req.enzymes,
        "circular": req.circular,
        "cuts": cuts,
        "fragment_lengths": _fragments(len(seq), cuts, req.circular),
    }
